+            type="${type}"
+            ${placeholder ? `placeholder="${placeholder}"` : ''}
+            ${requiredAttribute}
+            ${autocompleteAttribute}
+            ${inputmodeAttribute}
+            ${describedBy}
+          >
+          ${helper}
+        </div>
+      `;
+    }
+
+    function SubmitButton() {
+      return '<button type="submit">Send support request</button>';
+    }
+
+    function SupportContactForm() {
+      return [
+        TextField({
+          id: 'full-name',
+          label: 'Full name',
+          required: true,
+          autocomplete: 'name',
+          placeholder: 'Alex Morgan'
+        }),
+        TextField({
+          id: 'email-address',
+          label: 'Email address',
+          type: 'email',
+          required: true,
+          autocomplete: 'email',
