<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090d18;
      --panel: #111827;
      --panel-strong: #172033;
      --text: #f8fafc;
      --muted: #cbd5e1;
      --border: #334155;
      --accent: #7c3aed;
      --accent-bright: #a78bfa;
      --focus: #22d3ee;
      --shadow: rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(124, 58, 237, 0.24), transparent 32rem),
        radial-gradient(circle at bottom right, rgba(34, 211, 238, 0.14), transparent 28rem),
        var(--bg);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 10;
      transform: translateY(-150%);
      padding: 0.65rem 0.9rem;
      border-radius: 999px;
      color: #020617;
      background: var(--focus);
      font-weight: 700;
      text-decoration: none;
    }

