      padding: clamp(1.25rem, 4vw, 2.5rem);
      border: 1px solid rgba(148, 163, 184, 0.24);
      border-radius: 1.5rem;
      background: linear-gradient(145deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.92));
      box-shadow: 0 1.5rem 4rem var(--shadow);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent-bright);
      font-size: 0.875rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 6vw, 3.75rem);
      line-height: 1;
      letter-spacing: -0.06em;
    }

    .intro {
      max-width: 36rem;
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .required-note {
      margin: 0 0 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    form {
      display: grid;
      gap: 1.1rem;
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    label {
      color: var(--text);
      font-weight: 700;
    }

    .required-marker {
      color: var(--accent-bright);
      font-weight: 900;
    }

    input {
      width: 100%;
      min-height: 3.25rem;
      padding: 0.85rem 1rem;
      border: 1px solid var(--border);
      border-radius: 0.95rem;
      color: var(--text);
      background: var(--panel-strong);
      font: inherit;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    input::placeholder {
      color: #94a3b8;
      opacity: 1;
    }

    input:hover {
      border-color: #64748b;
      background: #1e293b;
    }

    input:focus {
      border-color: var(--focus);
      outline: 3px solid rgba(34, 211, 238, 0.34);
      outline-offset: 2px;
    }

    .helper-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.925rem;
    }

    button {
      justify-self: start;
      min-height: 3.25rem;
      margin-top: 0.6rem;
      padding: 0.9rem 1.4rem;
      border: 0;
      border-radius: 999px;
      color: #ffffff;
      background: linear-gradient(135deg, var(--accent), #2563eb);
      box-shadow: 0 1rem 2rem rgba(37, 99, 235, 0.28);
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 1.25rem 2.5rem rgba(37, 99, 235, 0.34);
    }

    button:focus {
      outline: 3px solid var(--focus);
      outline-offset: 4px;
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      .support-card,
      input,
      button {
        border: 1px solid ButtonText;
      }

      button {
        color: ButtonText;
        background: ButtonFace;
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="support-card" aria-labelledby="support-title">
      <p class="eyebrow">Support</p>
      <h1 id="support-title">Contact our team</h1>
      <p class="intro">Tell us how to reach you and a support specialist will follow up with next steps.</p>

      <form id="support-form" action="#" method="post">
        <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required fields</p>
        <div id="support-form-root"></div>
      </form>
    </section>
  </main>

  <script>
    function RequiredMarker() {
      return '<span class="required-marker" aria-hidden="true">*</span>';
    }

    function TextField({ id, label, type = 'text', required = false, autocomplete, inputmode, placeholder, helperText }) {
      const describedBy = helperText ? ` aria-describedby="${id}-help"` : '';
      const requiredAttribute = required ? ' required' : '';
      const autocompleteAttribute = autocomplete ? ` autocomplete="${autocomplete}"` : '';
      const inputmodeAttribute = inputmode ? ` inputmode="${inputmode}"` : '';
      const helper = helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : '';

      return `
        <div class="form-field">
          <label for="${id}">${label}${required ? ` ${RequiredMarker()}` : ''}</label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            ${placeholder ? `placeholder="${placeholder}"` : ''}
            ${requiredAttribute}
            ${autocompleteAttribute}
            ${inputmodeAttribute}
            ${describedBy}
          >
          ${helper}
        </div>
      `;
    }

    function SubmitButton() {
      return '<button type="submit">Send support request</button>';
    }

    function SupportContactForm() {
      return [
        TextField({
          id: 'full-name',
          label: 'Full name',
          required: true,
          autocomplete: 'name',
          placeholder: 'Alex Morgan'
        }),
        TextField({
          id: 'email-address',
          label: 'Email address',
          type: 'email',
          required: true,
          autocomplete: 'email',
          placeholder: 'alex@example.com'
        }),
        TextField({
          id: 'phone-number',
          label: 'Phone number (optional)',
          type: 'tel',
          autocomplete: 'tel',
          inputmode: 'tel',
          placeholder: '+1 555 123 4567',
          helperText: 'Use international format when possible, for example +1 555 123 4567.'
        }),
        SubmitButton()
      ].join('');
    }

    document.getElementById('support-form-root').innerHTML = SupportContactForm();
  </script>
</body>
</html>
